<?php
namespace App\Console\Commands;
use App\Domain\Network\Billing\SaasSubscriptionLifecycleService;use App\Domain\Network\Tenancy\Models\Tenant;use Illuminate\Console\Command;
final class ProcessSaasBillingCycle extends Command{protected$signature='zigo:subscriptions:billing-cycle {--tenant=} {--notify} {--suspend} {--dry-run}';protected$description='Procesa recordatorios y suspensión de suscripciones SaaS.';public function handle(SaasSubscriptionLifecycleService$service):int{$tenantId=null;if($this->option('tenant')){$tenant=Tenant::where('uuid',$this->option('tenant'))->orWhere('id',$this->option('tenant'))->first();if(!$tenant){$this->error('Tenant no encontrado.');return self::FAILURE;}$tenantId=$tenant->id;}$items=$service->expiring($tenantId)->merge($service->expired($tenantId))->unique('id');foreach($items as$s){$this->line($s->tenant->name.' · '.$s->current_period_end?->toDateString().' · '.$s->status);if($this->option('dry-run'))continue;if($this->option('notify'))$service->notifyDue($s);if($this->option('suspend')&&$s->current_period_end?->isPast())$service->suspendExpired($s);}$this->info($items->count().' suscripciones evaluadas.');return self::SUCCESS;}}
